-- dwh.lu_dot_place -- raw DOT city-code reference, Bright footprint only.
-- Source: 'City Lookup Table - WIP.xlsx', Data tab (40,411 national rows).
-- This is the UPSTREAM authority the research team's lookup was built from.
-- 6371 footprint rows.

CREATE TABLE IF NOT EXISTS dwh.lu_dot_place
(
   statename        VARCHAR(60)   ENCODE lzo
  ,county           VARCHAR(120)  ENCODE lzo
  ,cityname         VARCHAR(120)  ENCODE lzo
  ,stateabbr        CHAR(2)       ENCODE lzo
  ,statefipscode    CHAR(2)       ENCODE lzo
  ,countycode       VARCHAR(10)   ENCODE lzo
  ,countyfipscode   CHAR(5)       ENCODE lzo
  ,citycode         VARCHAR(10)   ENCODE lzo
  ,countycitycode   VARCHAR(20)   ENCODE lzo
  ,citynamenorm     VARCHAR(120)  ENCODE lzo
  ,countynamenorm   VARCHAR(120)  ENCODE lzo
)
DISTSTYLE ALL
SORTKEY (stateabbr, cityname);

TRUNCATE dwh.lu_dot_place;

