-- Normalized join keys. Suffix stripping matters: DOT says 'EWING TOWNSHIP'
-- where dim_listing says 'EWING'.
UPDATE dwh.lu_dot_place
SET citynamenorm = REGEXP_REPLACE(
      REPLACE(REPLACE(
        REGEXP_REPLACE(REGEXP_REPLACE(UPPER(TRIM(cityname)),'[^A-Z ]',''),' {2,}',' '),
        'SAINT ','ST '),'MOUNT ','MT '),
      ' (TOWNSHIP|TWP|BOROUGH|BORO)$',''),
    countynamenorm = REGEXP_REPLACE(REGEXP_REPLACE(UPPER(TRIM(county)),'[^A-Z ]',''),' {2,}',' ');
COMMIT;
